@Component("routing-handler")
@ProcessingGroup("routing-processing-group")
public class RoutingEventHandler {
	
	// core constructor
	RoutingEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateRoutingEvent
     */
    @EventHandler
    public void handle( CreateRoutingEvent event) {
        entityManager.persist(new Routing(event.getRoutingId(), event.getRoutingNumber(), event.getRevision(), event.getEffectivityStart(), event.getEffectivityEnd(), event.getItem(), event.getOperations(), event.getRoutingType(), event.getStatus()));
    }

    /*
     * @param	event UpdateRoutingEvent
     */
    @EventHandler
    public Routing handle( UpdateRoutingEvent event) {
    	entityManager.merge(new Routing(event.getRoutingId(), event.getRoutingNumber(), event.getRevision(), event.getEffectivityStart(), event.getEffectivityEnd(), event.getItem(), event.getOperations(), event.getRoutingType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteRoutingEvent
     */
    @EventHandler
    public void on( DeleteRoutingEvent event) {
    	Routing entity = new Routing();
   
    	// ------------------------------------------
    	// apply the RoutingId
    	// ------------------------------------------
    	entity.setRoutingId( event.getRoutingId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final RoutingRepository routingEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(RoutingEventHandler.class.getName());

}
